export function MobileFirst({
  wideOverride = {{wideOverride}},
  columns = {{columns}},
  label = "{{label}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430" }}>
      <p style={{ margin: "0 0 8px", fontWeight: 600 }}>{label}</p>
      <div style={{ display: "grid", gap: 8, gridTemplateColumns: wideOverride ? `repeat(${columns}, 1fr)` : "1fr" }}>
        <span style={{ height: 44, borderRadius: 8, background: accent }} />
        <span style={{ height: 44, borderRadius: 8, background: accent }} />
        <span style={{ height: 44, borderRadius: 8, background: accent }} />
      </div>
      <p style={{ margin: "10px 0 0", fontFamily: "ui-monospace, monospace", fontSize: 10, color: "#241430aa" }}>
        {wideOverride ? `@media (min-width: 640px) override: ${columns} columns` : "base: grid-template-columns: 1fr; (starts single-column, big touch targets)"}
      </p>
    </div>
  );
}
